//! Generates the Rust gRPC bindings from the `.proto` contracts at build time.
//!
//! Rust code is generated here rather than committed, because the Rust clients
//! (daemon, CLI, gateway) live in this same workspace and rebuild automatically.
//! The Dart and TypeScript clients, which live outside the cargo build, are
//! generated by `buf generate` and committed with a freshness check instead
//! (see `proto/buf.gen.yaml` and `tools/verify-proto-codegen.sh`).
//!
//! A file descriptor set is also emitted so tests and the daemon's authorization
//! interceptor can read the custom `required_permission` method option at
//! runtime (ARCHITECTURE.md §10.3).

use std::path::PathBuf;

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let proto_root = PathBuf::from("../../proto");
    let protos = [
        "networkhub/v1/common.proto",
        "networkhub/v1/system.proto",
        "networkhub/v1/events.proto",
        "networkhub/v1/monitor.proto",
    ];
    let proto_paths: Vec<PathBuf> = protos.iter().map(|p| proto_root.join(p)).collect();

    let out_dir = PathBuf::from(std::env::var("OUT_DIR")?);
    let descriptor_path = out_dir.join("networkhub_descriptor.bin");

    tonic_prost_build::configure()
        // The descriptor set is what lets the authz interceptor and the
        // annotation-coverage test see the required_permission option.
        .file_descriptor_set_path(&descriptor_path)
        // Derive serde on nothing by default; the wire types stay prost-native.
        .compile_protos(&proto_paths, &[proto_root])?;

    // Re-run codegen when any contract changes.
    for p in &proto_paths {
        println!("cargo:rerun-if-changed={}", p.display());
    }
    Ok(())
}
